<?php $escape = static fn (mixed $value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8'); ?><section class="section"><header class="admin-header"><div><h1>Notificaciones</h1><p>Consulta las asignaciones y reasignaciones de tickets dirigidas a tu cuenta.</p></div><a href="tickets.php" class="btn btn--secondary">Ver tickets</a></header><div class="card panel-card"><div class="notification-summary"><strong><?php echo (int) $unreadCount; ?></strong><span>notificación<?php echo $unreadCount === 1 ? '' : 'es'; ?> sin leer</span></div></div><?php if (!$notifications): ?><div class="card panel-card"><div class="ticket-observation-empty">No tienes notificaciones de asignación por ahora.</div></div><?php else: ?><div class="card panel-card"><div class="notification-list"><?php foreach ($notifications as $notification): ?><?php $actor = trim((string) ($notification['actor_display_name'] ?? $notification['actor_username'] ?? '')); ?><article class="notification-item <?php echo empty($notification['is_read']) ? 'notification-item--unread' : 'notification-item--read'; ?>"><div class="notification-item__body"><div class="notification-item__header"><h3><?php echo $escape($notification['title']); ?></h3><?php if (empty($notification['is_read'])): ?><span class="sidebar__badge">Nueva</span><?php endif; ?></div><p><?php echo $escape($notification['message']); ?></p><div class="ticket-meta"><?php echo $escape(date('d/m/Y H:i', strtotime($notification['created_at']))); ?><?php if ($actor): ?> · Actor: <?php echo $escape($actor); ?><?php endif; ?></div></div><div class="notification-item__actions"><a href="ticket_view.php?id=<?php echo (int) $notification['ticket_id']; ?>&amp;return=<?php echo urlencode('notifications.php'); ?>" class="btn btn--secondary">Abrir ticket</a></div></article><?php endforeach; ?></div></div><?php endif; ?></section>
